/* Echo experience: real server sessions, AI concierge, sandbox checkout and 3D controls. */
const echo={user:null,csrf:null,available:false};
function posterFallback(img){if(!(img instanceof HTMLImageElement)||img.dataset.fallback)return;const id=movies.findIndex(m=>img.alt.includes(m.title));if(id>=0){img.dataset.fallback='true';img.src='assets/posters/'+id+'.svg'}}
document.addEventListener('error',e=>posterFallback(e.target),true);
document.querySelectorAll('img').forEach(i=>{if(i.complete&&!i.naturalWidth)posterFallback(i)});
async function api(url,{method='GET',body}={}){
 const r=await fetch(url,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json','X-CSRF-Token':echo.csrf}: {})},...(body?{body:JSON.stringify(body)}:{})});
 let d;try{d=await r.json()}catch{throw new Error('The backend is unavailable. Run npm start to use accounts, AI and checkout.')}
 if(r.status===429){const wait=Number(r.headers.get('Retry-After'));throw new Error((d.error||'Too many requests.')+(Number.isFinite(wait)&&wait>0?' Try again in '+wait+' seconds.':''))}
 if(!r.ok)throw new Error(d.error||'The request could not be completed.');if(d.csrf)echo.csrf=d.csrf;return d;
}
const money=cents=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(cents/100);
const safeNext=()=>{const n=params.get('next');return n&&/^(booking|payment|bookings|account|event)\.html(?:\?[^#]*)?$/.test(n)?n:'account.html'};
const nextAccount=()=>{sessionStorage.setItem('orbitSeatDraft',JSON.stringify({url:location.pathname+location.search,seats}));location.href='account.html?next='+encodeURIComponent(location.pathname.split('/').pop()+location.search)};
function errorLine(id,message){const e=document.getElementById(id);if(e){e.textContent=message;e.hidden=false}else toast(message)}
document.body.classList.add('echo-immersive');
$('#signin').onclick=()=>location.href='account.html';
$('#signin').textContent='My echo ↗';
$('.footer-pages').insertAdjacentHTML('beforeend','<a href="account.html">Account</a><a href="ai.html">Echo AI</a><button id="cookie-settings">Cookie settings</button>');
$('header').insertAdjacentHTML('beforeend','<a class="ai-nav" href="ai.html"><span>✦</span> Echo AI</a>');
const aiFab=document.createElement('a');aiFab.href='ai.html';aiFab.className='ai-fab';aiFab.innerHTML='<span>✦</span><span>Ask Echo</span>';document.body.append(aiFab);
const immersiveControl=document.createElement('button');immersiveControl.className='motion-control';immersiveControl.setAttribute('aria-label','Pause 3D motion');immersiveControl.textContent='◈ 3D motion on';document.body.append(immersiveControl);
let motionOn=!matchMedia('(prefers-reduced-motion: reduce)').matches;immersiveControl.onclick=()=>{motionOn=!motionOn;document.body.classList.toggle('motion-paused',!motionOn);immersiveControl.textContent=motionOn?'◈ 3D motion on':'◈ 3D motion paused';immersiveControl.setAttribute('aria-label',motionOn?'Pause 3D motion':'Enable 3D motion');window.dispatchEvent(new CustomEvent('echo-motion',{detail:motionOn}))};
function cookiesPanel(){let consent;try{consent=JSON.parse(localStorage.getItem('orbitConsentV1')||'null')}catch{}if(consent)return;const panel=document.createElement('section');panel.className='cookie-panel';panel.setAttribute('aria-label','Cookie preferences');panel.innerHTML='<div class="cookie-mark">◉</div><div><h3>Your echo. Your choices.</h3><p>Essential cookies keep your account and checkout working. Optional preferences remember your 3D motion setting. No analytics or advertising cookies.</p><a href="privacy.html">How we use cookies ↗</a></div><div class="cookie-actions"><button data-consent="essential">Essential only</button><button data-consent="preferences" class="primary">Allow preferences</button></div>';document.body.append(panel)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-consent]');if(b){b.disabled=true;const preferences=b.dataset.consent==='preferences';try{await backendReady;await api('/api/consent',{method:'POST',body:{preferences}});localStorage.setItem('orbitConsentV1',JSON.stringify({essential:true,preferences,at:new Date().toISOString()}));$('.cookie-panel')?.remove();toast('Cookie preferences saved.')}catch(err){b.disabled=false;toast(err.message)}}if(e.target.closest('#cookie-settings')){localStorage.removeItem('orbitConsentV1');$('.cookie-panel')?.remove();cookiesPanel()}});
const backendReady=api('/api/session').then(data=>{echo.user=data.user;echo.available=true;$('#signin').textContent=echo.user?echo.user.name.split(' ')[0]+' ↗':'Sign in ↗';return data}).catch(err=>{echo.available=false;return {error:err.message}});
cookiesPanel();
function sceneSlot(target,mode='lobby'){if(!target)return;const host=document.createElement('div');host.className='echo-scene';host.dataset.scene=mode;host.innerHTML='<canvas aria-label="Interactive 3D echoal cinema sculpture"></canvas><span class="scene-caption">REAL-TIME 3D <i></i> MOVE TO EXPLORE</span>';target.append(host);window.dispatchEvent(new Event('echo-scenes'))}
if(page==='index'){
 $('.hero').classList.add('immersive-hero');$('.hero-copy').innerHTML='<div class="eyebrow"><span></span> WELCOME TO YOUR NEXT DIMENSION</div><p class="hero-kicker">Delhi, your escape is waiting.</p><h1>Step out of<br>the <em>ordinary.</em></h1><p class="hero-description">Bigger screens. Electric nights. Unforgettable stories.<br>Your next great memory is closer than you think.</p><div class="hero-actions"><a class="primary" href="movies.html">Find your next story <span>↗</span></a><a class="hero-ai-link" href="ai.html">✦ Let AI find your vibe</a></div><div class="hero-proof"><span>◎ IMAX & DOLBY</span><span>◈ LIVE IN DELHI</span><span>✦ CURATED FOR YOU</span></div>';
 $('.hero-label').innerHTML='ECHO EXPERIENCE <span>3D</span>';$('.hero-bottom').innerHTML='<span class="live-dot">●</span><span>DELHI-NCR · YOUR WORLD, EXPANDED</span><a href="events.html">Explore live experiences ↗</a>';sceneSlot($('.hero'));
 $('.city-editorial').insertAdjacentHTML('afterend','<a class="ai-invite" href="ai.html"><span class="ai-invite-icon">✦</span><div><span class="overline">MEET YOUR PERSONAL PLAN-MAKER</span><h2>“Something mind-bending. Two tickets. Under ₹1,000.”</h2><p>Tell Echo your mood. Find a film, discover an experience, make a night of it.</p></div><b>Ask Echo AI ↗</b></a>');
}else if(['account','ai','payment','privacy'].includes(page)){content('')}
else{const target=$('.page-intro')||$('.film-hero');if(target){target.classList.add('has-3d');sceneSlot(target,'mini')}}
function accountPage(mode='login'){
 document.title='Your account | EchoMyShow';const u=echo.user;
 if(u){content(bread('My echo')+`<section class="account-welcome"><div><div class="overline">WELCOME TO YOUR ECHO</div><h1>Good to see you,<br><em>${escapeHtml(u.name.split(' ')[0])}.</em></h1><p>Your stories. Your people. Your next great plan.</p></div><div class="account-avatar">${escapeHtml(u.name[0].toUpperCase())}</div></section><div class="account-layout"><aside class="account-menu"><a href="account.html" class="selected">◉ &nbsp; Profile</a><a href="bookings.html">▣ &nbsp; My bookings</a><a href="ai.html">✦ &nbsp; My AI concierge</a><button id="manage-cookies">◎ &nbsp; Cookie preferences</button><button id="logout">↗ &nbsp; Sign out</button></aside><section class="account-panel"><div class="overline">THE ESSENTIALS</div><h2>Your profile</h2><form id="account-profile"><label>Your name<input class="form-field" name="name" required minlength="2" maxlength="60" value="${escapeHtml(u.name)}" autocomplete="name"></label><label>Email address<input class="form-field" type="email" value="${escapeHtml(u.email)}" readonly></label><label>Home city<input class="form-field" value="Delhi-NCR" readonly></label><p>Member since ${new Date(u.created_at).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</p><p id="account-error" class="form-error" hidden role="alert"></p><button class="primary">Save changes ↗</button></form></section><aside class="account-perks"><span>✦</span><h2>Your next great<br>memory awaits.</h2><p>Find a big-screen escape, or let Echo pick something for your mood.</p><a href="ai.html">Meet your concierge ↗</a></aside></div>`);
 $('#account-profile').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await api('/api/account',{method:'PATCH',body:{name:new FormData(e.target).get('name')}});echo.user=d.user;$('#signin').textContent=d.user.name.split(' ')[0]+' ↗';accountPage();toast('Your profile is updated.')}catch(err){errorLine('account-error',err.message);b.disabled=false}};
 $('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:{}});echo.user=null;$('#signin').textContent='Sign in ↗';accountPage();toast('You’re signed out.')}catch(err){toast(err.message)}};
 $('#manage-cookies').onclick=()=>$('#cookie-settings').click();return;
 }
 const signup=mode==='register';content(bread('Your account')+`<section class="auth-layout"><div class="auth-story"><div class="overline">YOUR WORLD. MORE EXTRAORDINARY.</div><h1>A front-row seat<br>to <em>your next story.</em></h1><p>One account. A world of movie nights,<br>live moments and unforgettable plans.</p><div class="auth-scene"></div><div class="auth-story-footer"><span>◉ ECHOMYSHOW</span><span>MADE FOR THE MOMENTS.</span></div></div><div class="auth-form-panel"><span class="auth-icon">◈</span><div class="auth-tabs"><button id="login-tab" class="${!signup?'selected':''}">Sign in</button><button id="register-tab" class="${signup?'selected':''}">Create account</button></div><h2>${signup?'Make yourself at home.':'Welcome back.'}</h2><p>${signup?'Your next great memory starts here.':'Your echo is right where you left it.'}</p><form id="real-auth">${signup?'<label>Full name<input class="form-field" name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="Your name"></label>':''}<label>Email address<input class="form-field" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<div class="password-wrap"><input class="form-field" id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="10" maxlength="128" required placeholder="At least 10 characters"><button type="button" id="show-password" aria-label="Show password">Show</button></div></label><p id="auth-error" class="form-error" role="alert" hidden></p><button class="primary auth-submit">${signup?'Create my account':'Enter my echo'} ↗</button></form><div class="auth-note">◎ Passwords are hashed. Sessions use essential cookies.</div><p class="auth-privacy">Your details stay with your local EchoMyShow account.<br><a href="privacy.html">Privacy & cookie information ↗</a></p></div></section>`);sceneSlot($('.auth-scene'));
 $('#login-tab').onclick=()=>accountPage('login');$('#register-tab').onclick=()=>accountPage('register');$('#show-password').onclick=()=>{const i=$('#auth-password');i.type=i.type==='password'?'text':'password';$('#show-password').textContent=i.type==='password'?'Show':'Hide';$('#show-password').setAttribute('aria-label',i.type==='password'?'Show password':'Hide password')};
 $('#real-auth').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('.auth-submit');b.disabled=true;b.textContent='Opening your echo…';try{await backendReady;const values=Object.fromEntries(new FormData(e.target));const d=await api('/api/auth/'+(signup?'register':'login'),{method:'POST',body:values});echo.user=d.user;location.href=safeNext()}catch(err){errorLine('auth-error',err.message);b.disabled=false;b.textContent=signup?'Create my account ↗':'Enter my echo ↗'}};
}
function aiPage(){document.title='Echo AI concierge | EchoMyShow';content(bread('Echo AI')+`<section class="ai-layout"><aside class="ai-introduction"><div class="overline">A LITTLE INTELLIGENCE. A LOT OF POSSIBILITY.</div><h1>Find your<br><em>kind of<br>extraordinary.</em></h1><p>Meet Echo. Your personal guide to great films and unforgettable Delhi nights.</p><div class="ai-orb-scene"></div><div class="ai-capabilities"><span>✦ Mood-based movie picks</span><span>◎ Plans around your budget</span><span>◈ Spoiler-free recommendations</span></div><small>Your messages are sent to Google Gemini to generate responses. Listings are sample data.</small></aside><section class="ai-chat"><div class="ai-chat-top"><span class="echo-avatar">✦</span><div><strong>Echo</strong><small>Your AI movie concierge</small></div><span class="powered">POWERED BY GEMINI</span></div><div id="chat-messages" class="chat-messages" aria-live="polite"><div class="chat-message assistant"><span class="echo-avatar">✦</span><p>Hey, Delhi. What are we in the mood for?<br><br>A mind-bending film, a laugh-out-loud evening, or a plan for two? Tell me a little about your vibe.</p></div><div class="ai-suggestions"><button data-prompt="Recommend a mind-bending English film, no spoilers.">A mind-bending movie ↗</button><button data-prompt="Plan a movie night for two in Delhi under ₹1000 using your sample catalogue.">Date night under ₹1,000 ↗</button><button data-prompt="I want an uplifting live experience in Delhi. What do you suggest?">Something live in Delhi ↗</button></div></div><form id="ai-chat-form"><label class="sr-only" for="ai-message">Message Echo</label><textarea id="ai-message" placeholder="Tell Echo your mood…" maxlength="1500" required rows="2"></textarea><button type="submit" id="send-ai" aria-label="Send message">↗</button></form><p class="ai-disclaimer">AI can make mistakes. Check the listing before you make plans.</p></section></section>`);sceneSlot($('.ai-orb-scene'),'orb');const history=[];
 const send=async value=>{const input=$('#ai-message');const message=(value||input.value).trim();if(!message||$('#send-ai').disabled)return;input.value='';$('.ai-suggestions')?.remove();const target=$('#chat-messages');target.insertAdjacentHTML('beforeend',`<div class="chat-message user"><p>${escapeHtml(message)}</p></div><div class="chat-message assistant pending"><span class="echo-avatar">✦</span><p>Finding your echo<span class="thinking"> · · ·</span></p></div>`);target.scrollTop=target.scrollHeight;$('#send-ai').disabled=true;try{await backendReady;const d=await api('/api/ai/chat',{method:'POST',body:{message,history}});$('.pending').innerHTML='<span class="echo-avatar">✦</span><p>'+escapeHtml(d.reply).replace(/\n/g,'<br>')+'</p>';$('.pending').classList.remove('pending');history.push({role:'user',text:message},{role:'model',text:d.reply})}catch(err){$('.pending').innerHTML='<span class="echo-avatar">!</span><p>'+escapeHtml(err.message)+'</p>';$('.pending').classList.add('chat-error');$('.pending').classList.remove('pending')}finally{$('#send-ai').disabled=false;target.scrollTop=target.scrollHeight}};
 $('#ai-chat-form').onsubmit=e=>{e.preventDefault();send()};$$('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt));$('#ai-message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};
}
function normalizedDate(){let offset=bookingDate==='Tomorrow'?1:bookingDate==='Today'?0:2;return new Date(Date.now()+offset*86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})}
async function newMovieOrder(){await backendReady;if(!echo.user)return nextAccount();if(!seats.length)return toast('Choose your seats first.');const btn=$('#checkout button')||$('#continue-booking');if(btn)btn.disabled=true;try{const d=await api('/api/orders',{method:'POST',body:{kind:'movie',itemId:movies.indexOf(selectedMovie),venueId:venues.indexOf(cinema),date:normalizedDate(),time:bookingTime,seats}});sessionStorage.removeItem('orbitSeatDraft');location.href='payment.html?order='+encodeURIComponent(d.order.id)}catch(err){toast(err.message);if(btn)btn.disabled=false}}
if(page==='booking'){
 const draft=sessionStorage.getItem('orbitSeatDraft');if(draft)try{const d=JSON.parse(draft);if(d.url===location.pathname+location.search){seats=d.seats;seatView()}}catch{}
 const originalCheckout=checkout;checkout=function(){originalCheckout();if($('#checkout')){$('#checkout').innerHTML='<div class="checkout-handoff"><span>◈</span><h3>Your seats. Your moment.</h3><p>Continue to EchoPay to review your order and complete a sandbox payment.</p><div class="sandbox-label">SANDBOX · NO REAL MONEY</div><button type="button" class="primary" id="open-echopay">Continue to EchoPay ↗</button></div>';$('#open-echopay').onclick=newMovieOrder}};
}
if(page==='event')$('#reserve-event').onclick=async()=>{await backendReady;if(!echo.user){location.href='account.html?next='+encodeURIComponent('event.html'+location.search);return}const b=$('#reserve-event');b.disabled=true;try{const d=await api('/api/orders',{method:'POST',body:{kind:'event',itemId:Number(params.get('id'))||0,quantity:+$('#event-qty').value}});location.href='payment.html?order='+d.order.id}catch(err){toast(err.message);b.disabled=false}};
async function paymentPage(){document.title='EchoPay · Sandbox checkout';await backendReady;if(!echo.user){content(bread('EchoPay')+'<div class="empty-state"><span>◈</span><h2>Your account keeps your plans together.</h2><p>Sign in to continue to your sandbox checkout.</p><a class="primary" href="account.html?next='+encodeURIComponent('payment.html'+location.search)+'">Sign in ↗</a></div>');return}const id=params.get('order');let order;try{({order}=await api('/api/orders/'+encodeURIComponent(id||'')))}catch(err){content(bread('EchoPay')+'<div class="empty-state"><h2>Let’s find your booking.</h2><p>'+escapeHtml(err.message)+'</p><a class="primary" href="bookings.html">My bookings ↗</a></div>');return}
 if(order.status==='confirmed'){receipt(order);return}if(order.status==='failed'){content(bread('EchoPay')+'<div class="empty-state"><span>↻</span><h2>The sandbox payment was declined.</h2><p>No money was charged. Your seats have been released.</p><a class="primary" href="movies.html">Choose another show ↗</a></div>');return}
 content(bread('EchoPay')+`<div class="pay-header"><a href="index.html" class="pay-logo">◈ echo<span>pay</span></a><span class="sandbox-label">SANDBOX CHECKOUT</span><span class="pay-secure">◎ SERVER-VERIFIED ORDER</span></div><div class="payment-layout"><section class="payment-panel"><div class="overline">ONE STEP FROM A GREAT MEMORY</div><h1>Make it a plan.</h1><p class="pay-description">Choose how you’d like to try your sandbox checkout.</p><div class="payment-methods"><button data-method="demo-upi" class="selected"><span>↗</span>Demo UPI</button><button data-method="demo-card"><span>▣</span>Test card</button><button data-method="demo-wallet"><span>◈</span>Echo Wallet</button></div><div id="payment-method-body"></div><label class="pay-outcome">Sandbox outcome <select id="pay-outcome"><option value="success">Successful payment</option><option value="decline">Declined payment</option></select></label><p id="payment-error" class="form-error" role="alert" hidden></p><button class="primary pay-button" id="pay-order">Simulate payment · ${money(order.total)} ↗</button><p class="pay-disclaimer">This is a simulation. No bank account, card, UPI ID or money is used.</p></section><aside class="order-summary"><span class="overline">YOUR NEXT GREAT MEMORY</span><h2>${escapeHtml(order.title)}</h2><p>⌖ ${escapeHtml(order.venue)}</p><div class="order-summary-details"><div><small>WHEN</small><strong>${escapeHtml(order.show_date)} · ${escapeHtml(order.show_time)}</strong></div><div><small>SEATS / TICKETS</small><strong>${order.seats.map(escapeHtml).join(', ')}</strong></div></div><div class="summary-line"><span>Tickets</span><strong>${money(order.subtotal)}</strong></div><div class="summary-line"><span>Convenience fee (3%)</span><strong>${money(order.fee)}</strong></div><div class="summary-line summary-total"><span>Total</span><strong>${money(order.total)}</strong></div><div class="hold-notice">◷ Seats held for 10 minutes from order creation.</div><small>Order ${escapeHtml(order.id)}</small></aside></div>`);
 let method='demo-upi';function methodUI(){const html={'demo-upi':'<div class="upi-preview"><div class="upi-orb">↗</div><h3>Instant plans. Zero real payments.</h3><p>Use a simulated UPI account for this sandbox transaction.</p><div class="demo-identity"><span>echo.demo@sandbox</span><b>DEMO</b></div></div>','demo-card':'<div class="test-card"><div><strong>ECHOPAY</strong><span>SANDBOX</span></div><span class="card-chip">▦</span><p>•••• &nbsp; •••• &nbsp; •••• &nbsp; 4242</p><div><span>ECHO TEST CARD</span><span>12 / 30</span></div></div><p class="test-card-note">Preconfigured test card. No real card details are requested or stored.</p>','demo-wallet':'<div class="wallet-preview"><span>◈</span><small>ECHO DEMO WALLET</small><h2>'+money(order.total)+'</h2><p>Sandbox credits for this order.<br>These have no monetary value.</p></div>'};$('#payment-method-body').innerHTML=html[method]}methodUI();$$('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;$$('[data-method]').forEach(x=>x.classList.toggle('selected',x===b));methodUI()});
 $('#pay-order').onclick=async()=>{const b=$('#pay-order');b.disabled=true;b.textContent='Processing sandbox payment…';try{const d=await api('/api/orders/'+order.id+'/pay',{method:'POST',body:{method,outcome:$('#pay-outcome').value}});if(d.order.status==='confirmed')receipt(d.order);else paymentPage()}catch(err){errorLine('payment-error',err.message);b.disabled=false;b.textContent='Retry sandbox payment ↗'}};
}
function receipt(o){content(bread('Your ticket')+`<section class="receipt"><div class="receipt-symbol">✓</div><div class="overline">YOUR NEXT GREAT MEMORY IS BOOKED</div><h1>You’re going.</h1><p>Sandbox payment completed. No real money was charged.</p><div class="receipt-ticket"><div class="receipt-ticket-top"><span>ECHOMYSHOW</span><span>DEMO TICKET</span></div><h2>${escapeHtml(o.title)}</h2><p>${escapeHtml(o.venue)}</p><div class="ticket-info"><div><small>DATE & TIME</small><strong>${escapeHtml(o.show_date)} · ${escapeHtml(o.show_time)}</strong></div><div><small>SEATS / TICKETS</small><strong>${o.seats.map(escapeHtml).join(', ')}</strong></div></div><div class="receipt-barcode" aria-hidden="true"></div><small>${escapeHtml(o.id)}</small><div class="summary-line"><span>Simulated payment</span><strong>${money(o.total)}</strong></div><p class="receipt-invalid">Not valid for venue admission.</p></div><div class="receipt-actions"><a class="primary" href="bookings.html">View my bookings ↗</a><button id="print-receipt">Print demo receipt ↗</button></div></section>`);$('#print-receipt').onclick=()=>window.print()}
async function serverBookings(){await backendReady;if(!echo.user){content(bread('My bookings')+intro('YOUR GOOD TIMES, TOGETHER','Your next great plan lives here.','Sign in to find your database-backed bookings and sandbox receipts.')+'<div class="empty-state"><span>◈</span><h2>Your tickets, in your echo.</h2><p>Sign in to view bookings saved to your account.</p><a class="primary" href="account.html?next=bookings.html">Sign in ↗</a></div>');return}try{const d=await api('/api/orders');content(bread('My bookings')+intro('YOUR GOOD TIMES, TOGETHER','Plans worth looking forward to.','Your account’s bookings and sandbox payment receipts.')+(d.orders.length?`<div class="bookings-grid">${d.orders.map(o=>`<article class="saved-ticket"><div class="ticket-top"><span>${o.status==='confirmed'?'SANDBOX CONFIRMED':o.status==='pending'?'AWAITING SANDBOX PAYMENT':'PAYMENT DECLINED'}</span><b>↗</b></div><h2>${escapeHtml(o.title)}</h2><p>${escapeHtml(o.venue)}</p><div class="ticket-info"><div><small>DATE & TIME</small><strong>${escapeHtml(o.show_date)} · ${escapeHtml(o.show_time)}</strong></div><div><small>SEATS</small><strong>${o.seats.map(escapeHtml).join(', ')}</strong></div></div><div class="ticket-perforation"></div><div class="ticket-code"><span>${escapeHtml(o.id)}</span><strong>${money(o.total)}</strong></div><a class="text-link" href="payment.html?order=${o.id}">${o.status==='pending'?'Continue checkout':'View receipt'} ↗</a></article>`).join('')}</div>`:'<div class="empty-state"><span>◉</span><h2>A new story is waiting.</h2><p>No bookings yet. Find a film you’ll love.</p><a class="primary" href="movies.html">Find a movie ↗</a></div>'))}catch(err){toast(err.message)}}
if(page==='account'){backendReady.then(()=>accountPage())}if(page==='ai')aiPage();if(page==='payment')paymentPage();if(page==='bookings')serverBookings();
if(page==='privacy'){document.title='Privacy & cookies | EchoMyShow';content(bread('Privacy & cookies')+intro('YOUR ECHO. YOUR CHOICES.','A little clarity goes a long way.','How this local application handles your information.')+'<section class="utility-panel privacy-copy"><h2>Your account</h2><p>Account names, email addresses and password hashes are stored in a local SQLite database. Passwords are hashed using scrypt with a unique salt. Account sessions use an HttpOnly, SameSite cookie.</p><h2>Essential cookies</h2><p>The session cookie keeps your account signed in. The consent cookie records your cookie choice. These support account access, request protection and checkout.</p><h2>Optional preferences</h2><p>If allowed, your 3D motion preference is remembered on this browser. Analytics and advertising cookies are not used.</p><h2>AI messages</h2><p>Messages you send to Echo AI, together with recent conversation context, are sent to Google Gemini. Chat messages are not saved in the local database. Do not include sensitive information in chat.</p><h2>Sandbox payments</h2><p>Order and simulated payment records are saved to your account. No real payment is made. No card number, UPI credentials or bank details are requested or stored.</p><h2>External images and fonts</h2><p>Movie posters, photography and fonts load from TMDB, Unsplash and Google Fonts. These services receive standard network request information, including your IP address.</p><button class="primary" id="privacy-cookie">Manage cookie preferences ↗</button></section>');$('#privacy-cookie').onclick=()=>$('#cookie-settings').click()}
// Pointer tilt gives browse cards depth while preserving native links and keyboard access.
document.addEventListener('pointermove',e=>{if(!motionOn||e.pointerType==='touch')return;const card=e.target.closest('.movie-card,.event-card,.deal-card,.saved-ticket');if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-8+'deg');card.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*8+'deg');card.classList.add('tilting')});document.addEventListener('pointerout',e=>{const c=e.target.closest('.tilting');if(c&&!c.contains(e.relatedTarget)){c.classList.remove('tilting');c.style.setProperty('--rx','0deg');c.style.setProperty('--ry','0deg')}});
window.addEventListener('echo-motion',e=>{let prefs;try{prefs=JSON.parse(localStorage.getItem('orbitConsentV1')||'null')}catch{}if(prefs?.preferences)localStorage.setItem('orbitMotion',String(e.detail))});
if(localStorage.getItem('orbitMotion')==='false'&&motionOn)immersiveControl.click();
if(page==='booking'){const mountTheater=()=>{if($('.seat-grid')&&!$('.theater-preview')){const host=document.createElement('div');host.className='theater-preview';host.innerHTML='<div class="theater-label"><span>◈ YOUR CINEMA, IN 3D</span><small>Click a seat to select · Accessible seat map below</small></div>';$('.seat-grid').insertAdjacentElement('beforebegin',host);sceneSlot(host,'seats')}};new MutationObserver(mountTheater).observe(main,{childList:true,subtree:true});mountTheater()}


